import{_ as a,a as o,b as i}from"./chunks/payload-3.Dh4aD50w.js";import{_ as r,o as l,c as e,a5 as d}from"./chunks/framework.CcrBcQWS.js";const f=JSON.parse('{"title":"3. Payload 설정","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/add-on/payload-setting.md","filePath":"ko/guides/add-on/payload-setting.md","lastUpdated":1787021357000}'),n={name:"ko/guides/add-on/payload-setting.md"};function s(g,t,c,h,p,u){return l(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="_3-payload-설정" tabindex="-1">3. Payload 설정 <a class="header-anchor" href="#_3-payload-설정" aria-label="Permalink to &quot;3. Payload 설정&quot;">​</a></h1><p><strong>목표:</strong> RBQGUI에서 추가 모듈의 <strong>질량</strong>과 <strong>X/Y/Z 오프셋</strong>을 입력하여, 로봇이 보행 중 이를 반영하도록 설정합니다.</p><p><strong>사전 조건:</strong> 2단계 <a href="/RBQ/nightly/ko/guides/add-on/rail-spring-nut.html">레일 &amp; 스프링 너트</a> 완료 — 추가 모듈이 레일에 물리적으로 장착되어 있어야 합니다.</p><h2 id="시작하기-전에" tabindex="-1">시작하기 전에 <a class="header-anchor" href="#시작하기-전에" aria-label="Permalink to &quot;시작하기 전에&quot;">​</a></h2><ul><li>로봇을 <strong>평탄하고 안전한 바닥</strong>에 놓으세요.</li><li>RBQGUI가 로봇에 <strong>연결</strong>되어 있어야 합니다 (<a href="/RBQ/nightly/ko/guides/common/controller-wifi-connect.html">컨트롤러 &amp; Wi-Fi</a> 완료).</li><li>추가 모듈 무게중심의 **X / Y / Z 오프셋(m)**을 로봇 본체 중심 기준으로 측정해 두세요.</li></ul><h2 id="절차" tabindex="-1">절차 <a class="header-anchor" href="#절차" aria-label="Permalink to &quot;절차&quot;">​</a></h2><ol><li>RBQGUI에서 <strong>Payload Configuration</strong>을 엽니다.</li><li>상단 입력 필드에 값을 입력합니다: <ul><li><strong>Mass (kg)</strong> — 적재물 질량</li><li><strong>Offset X / Y / Z (m)</strong> — 로봇 좌표계 기준 적재물 중심 위치</li></ul></li></ol><figure style="text-align:center;"><img src="'+a+'" alt="Payload Configuration 입력 화면" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Payload Configuration — 값 입력</figcaption></figure><ol start="3"><li><strong>+ Add</strong>를 눌러 <strong>Added Payload</strong> 목록에 추가합니다.</li><li>입력값이 올바른지 확인한 뒤 <strong>Set Payload</strong>를 클릭합니다.</li></ol><figure style="text-align:center;"><img src="'+o+'" alt="Added Payload 목록" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Added Payload 목록</figcaption></figure><ol start="5"><li>확인 팝업이 표시되면 질량/오프셋을 다시 확인하고 <strong>Confirm</strong>을 눌러 로봇에 적용합니다.</li></ol><figure style="text-align:center;"><img src="'+i+'" alt="Payload 적용 확인 팝업" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">적용 확인</figcaption></figure><ol start="6"><li>필요 시 <strong>Load Payload</strong>를 눌러 로봇에 현재 적용된 값을 다시 읽어와 입력값과 일치하는지 확인합니다.</li></ol><h2 id="버튼-설명" tabindex="-1">버튼 설명 <a class="header-anchor" href="#버튼-설명" aria-label="Permalink to &quot;버튼 설명&quot;">​</a></h2><table tabindex="0"><thead><tr><th>버튼</th><th>기능</th></tr></thead><tbody><tr><td><strong>+ Add</strong></td><td>입력한 질량/오프셋을 후보 목록에 추가</td></tr><tr><td><strong>Clear</strong></td><td>현재 입력 필드 초기화</td></tr><tr><td><strong>Set Payload</strong></td><td>Added Payload 목록을 로봇에 적용</td></tr><tr><td><strong>Load Payload</strong></td><td>로봇에 현재 적용된 payload 값 불러오기</td></tr><tr><td><strong>Reset Payload</strong></td><td>Payload를 기본값(없음)으로 초기화</td></tr></tbody></table><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>Payload 등록만으로는 충분하지 않습니다 — 다음 단계의 ZMP 캘리브레이션을 통해 새로운 하중 조건에서 균형을 맞추는 자세 보정이 함께 필요합니다.</p></div></div><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>Payload 등록이 끝났다면 새로운 무게 조건에서 균형을 맞추기 위해 ZMP 캘리브레이션을 수행합니다:</p><p><strong><a href="/RBQ/nightly/ko/guides/add-on/zmp-calibration.html">→ 4. ZMP 캘리브레이션</a></strong></p>',19)])])}const P=r(n,[["render",s]]);export{f as __pageData,P as default};
